  'e5fb310b-7f5f-4d1a-bf06-cc16d4be4ed4',
  'do_dung_gia_dinh',
  'Đồ dùng gia đình',
  'A1',
  'Nội thất, đồ gia dụng trong phòng khа́ch, phòng bếp, phòng ngủ, phòng tắm, phòng giặt kèm thao tа́c sử dụng.',
  'home',
  '#d97706',
  TRUE,
